'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var truncf = require( '@stdlib/math/base/special/truncf' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Wraps a value on the half-open interval `[min,max)` for single-precision floating-point numbers.
*
* @param {number} v - input value
* @param {number} min - minimum value
* @param {number} max - maximum value
* @returns {number} wrapped value
*
* @example
* var v = wrapf( 3.14, 0.0, 5.0 );
* // returns ~3.14
*
* v = wrapf( -3.14, 0.0, 5.0 );
* // returns ~1.86
*
* v = wrapf( 10.0, 0.0, 5.0 );
* // returns 0.0
*
* v = wrapf( -0.0, 0.0, 5.0 );
* // returns 0.0
*
* v = wrapf( 0.0, -0.0, 5.0 );
* // returns 0.0
*
* v = wrapf( NaN, 0.0, 5.0 );
* // returns NaN
*
* v = wrapf( 0.0, NaN, 5.0 );
* // returns NaN
*
* v = wrapf( 3.14, 0.0, NaN );
* // returns NaN
*
* v = wrapf( 3.14, 5.0, 0.0 );
* // returns NaN
*/
function wrapf( v, min, max ) {
	var delta;
	if (
		isnanf( v ) ||
		isnanf( min ) ||
		isnanf( max ) ||
		max <= min
	) {
		return NaN;
	}

	// Normalize +-0 to +0...
	if ( v === 0.0 ) {
		v = 0.0;
	}
	if ( min === 0.0 ) {
		min = 0.0;
	}
	if ( max === 0.0 ) {
		max = 0.0;
	}

	// Simple case where value is already within range...
	if ( min <= v && v < max ) {
		return v;
	}

	// Perform range reduction...
	delta = max - min;
	if ( v < min ) {
		v += delta * ( truncf( ( min - v ) / delta ) + 1.0 );
	}
	return float64ToFloat32( float64ToFloat32( min ) + float64ToFloat32( float64ToFloat32( float64ToFloat32( v ) - float64ToFloat32( min ) ) % float64ToFloat32( delta ) ) );
}


// EXPORTS //

module.exports = wrapf;
